export * as Select from './select.tsx';
export type {
  ContentProps as SelectContentProps,
  OptionProps as SelectOptionProps,
  TriggerOwnProps as SelectTriggerOwnProps,
  TriggerProps as SelectTriggerProps,
} from './select.tsx';

@layer hj.components {
  /*
   * Customise: --hj-select-height · --hj-select-radius · --hj-select-popup-radius
   * · --hj-select-item-height. Set them on the trigger, the popup or any ancestor.
   */
  .hj-select-label {
    font-size: 13px;
    font-weight: 600;
    line-height: 1.3;
    color: var(--hj-fg);
    cursor: default;
  }

  /* Closed: drawn like a text field, so forms read as one family. */
  .hj-select-trigger {
    --_h: var(--hj-select-height, calc(48px * var(--hj-density-size)));
    --_ring: var(--hj-line);
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: calc(10px * var(--hj-density));
    min-width: 200px;
    width: 100%;
    height: var(--_h);
    padding: 0 calc(12px * var(--hj-density)) 0 calc(14px * var(--hj-density));
    border: 0;
    border-radius: var(--hj-select-radius, var(--hj-radius-sm));
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--_ring);
    color: var(--hj-fg);
    font: 500 15px / 1.2 var(--hj-font-sans);
    text-align: left;
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    -webkit-tap-highlight-color: transparent;
    transition:
      box-shadow var(--hj-dur-fast) var(--hj-ease-out),
      background-color var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-select-trigger[data-size='sm'] {
    --_h: var(--hj-select-height, calc(40px * var(--hj-density-size)));
    font-size: 14px;
    padding: 0 calc(10px * var(--hj-density)) 0 calc(12px * var(--hj-density));
  }
  .hj-select-trigger[data-size='lg'] {
    --_h: var(--hj-select-height, calc(56px * var(--hj-density-size)));
    font-size: 16px;
  }
  .hj-select-trigger:hover:not([data-disabled]):not(:focus-visible):not([data-popup-open]) {
    --_ring: color-mix(in srgb, var(--hj-fg) 22%, transparent);
  }
  .hj-select-trigger:focus-visible,
  .hj-select-trigger[data-popup-open] {
    --_ring: var(--hj-accent);
    box-shadow: inset 0 0 0 1.5px var(--_ring);
    outline: none;
  }
  .hj-select-trigger[data-invalid] {
    --_ring: var(--hj-danger);
    box-shadow: inset 0 0 0 1.5px var(--_ring);
  }
  .hj-select-trigger[data-disabled] {
    background: transparent;
    color: var(--hj-fg-mute);
    cursor: not-allowed;
  }

  .hj-select-value {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .hj-select-value[data-placeholder] {
    color: var(--hj-fg-mute);
    font-weight: 400;
  }
  .hj-select-icon {
    display: inline-flex;
    flex: none;
    font-size: 18px;
    line-height: 0;
    color: var(--hj-fg-mute);
    transition:
      color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle);
  }
  .hj-select-icon svg {
    width: 1em;
    height: 1em;
  }
  .hj-select-trigger[data-popup-open] .hj-select-icon {
    color: var(--hj-fg);
  }

  .hj-select-positioner {
    z-index: var(--hj-z-popover);
    outline: none;
  }
  .hj-select-backdrop {
    position: fixed;
    inset: 0;
  }

  /* Open: grows from the trigger, lifts off the page — the one surface allowed a shadow. */
  .hj-select-popup {
    box-sizing: border-box;
    min-width: var(--anchor-width);
    max-width: var(--available-width);
    border: 1px solid var(--hj-line);
    border-radius: var(--hj-select-popup-radius, var(--hj-radius-md));
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface-2);
    background-clip: padding-box;
    box-shadow: var(--hj-shadow-lift);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    outline: none;
    transform-origin: var(--transform-origin);
    transition:
      transform var(--hj-dur-snappy) var(--hj-ease-snappy),
      opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-select-popup[data-starting-style],
  .hj-select-popup[data-ending-style] {
    opacity: 0;
    transform: scale(0.96);
  }
  .hj-select-popup[data-ending-style] {
    transition-duration: var(--hj-dur-fast);
    transition-timing-function: var(--hj-ease-out);
  }
  /* Aligned over the trigger: no travel, only a fade. */
  .hj-select-popup[data-side='none'] {
    min-width: calc(var(--anchor-width) + 16px);
  }
  .hj-select-popup[data-side='none'][data-starting-style],
  .hj-select-popup[data-side='none'][data-ending-style] {
    transform: none;
  }

  .hj-select-list {
    position: relative;
    box-sizing: border-box;
    max-height: var(--available-height);
    padding: calc(6px * var(--hj-density));
    overflow-y: auto;
    scroll-padding-block: 28px;
    outline: none;
  }

  .hj-select-item {
    display: grid;
    grid-template-columns: 18px minmax(0, 1fr);
    column-gap: calc(10px * var(--hj-density));
    align-items: center;
    min-height: var(--hj-select-item-height, calc(40px * var(--hj-density-size)));
    padding: calc(6px * var(--hj-density)) calc(14px * var(--hj-density))
      calc(6px * var(--hj-density)) calc(10px * var(--hj-density));
    border-radius: var(--hj-radius-xs);
    corner-shape: var(--hj-corner-shape, round);
    font-size: 14.5px;
    font-weight: 500;
    line-height: 1.3;
    color: var(--hj-fg);
    cursor: default;
    user-select: none;
    outline: none;
    transition: background-color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-select-item[data-highlighted] {
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
  }
  .hj-select-item[data-selected] .hj-select-item-text {
    font-weight: 600;
  }
  .hj-select-item[data-disabled] {
    opacity: 0.4;
  }
  .hj-select-item-indicator {
    grid-column: 1;
    display: inline-flex;
    font-size: 17px;
    line-height: 0;
    color: var(--hj-accent);
    animation: hj-fade-in var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-select-item-indicator svg {
    width: 1em;
    height: 1em;
  }
  .hj-select-item-text {
    grid-column: 2;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .hj-select-item-description {
    grid-column: 2;
    font-size: 12.5px;
    font-weight: 400;
    line-height: 17px;
    color: var(--hj-fg-mute);
  }

  .hj-select-group + .hj-select-group {
    margin-top: calc(4px * var(--hj-density));
  }
  .hj-select-group-label {
    padding: calc(10px * var(--hj-density)) calc(10px * var(--hj-density))
      calc(4px * var(--hj-density)) calc(38px * var(--hj-density));
    font: var(--hj-type-eyebrow);
    letter-spacing: var(--hj-tracking-eyebrow);
    text-transform: uppercase;
    color: var(--hj-fg-mute);
    cursor: default;
  }
  .hj-select-separator {
    height: 1px;
    margin: calc(6px * var(--hj-density)) calc(4px * var(--hj-density));
    background: var(--hj-line);
  }

  .hj-select-scroll-arrow {
    position: absolute;
    left: 0;
    z-index: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 24px;
    background: var(--hj-surface-2);
    color: var(--hj-fg-mute);
    font-size: 14px;
    line-height: 0;
    cursor: default;
  }
  .hj-select-scroll-arrow svg {
    width: 1em;
    height: 1em;
  }
  .hj-select-scroll-arrow[data-direction='up'] {
    top: 0;
    border-radius: var(--hj-radius-md) var(--hj-radius-md) 0 0;
    corner-shape: var(--hj-corner-shape, round);
  }
  .hj-select-scroll-arrow[data-direction='down'] {
    bottom: 0;
    border-radius: 0 0 var(--hj-radius-md) var(--hj-radius-md);
    corner-shape: var(--hj-corner-shape, round);
  }
  .hj-select-scroll-arrow::before {
    content: '';
    position: absolute;
    left: 0;
    width: 100%;
    height: 100%;
  }
  .hj-select-scroll-arrow[data-direction='up'][data-side='none']::before {
    top: -100%;
  }
  .hj-select-scroll-arrow[data-direction='down'][data-side='none']::before {
    bottom: -100%;
  }

  .hj-select-arrow {
    width: 12px;
    height: 6px;
  }
}

'use client';
import { Select as Base } from '@base-ui/react/select';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { part } from '../../system/part.tsx';
import type { HanjiPart } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';
import { ThemeScope } from '../../system/theme.tsx';

/** State owner: value, onValueChange, items, multiple, open. Generic over the value type. */
export const Root: typeof Base.Root = Base.Root;
export const Label: HanjiPart<typeof Base.Label> = part(
  Base.Label,
  'Select.Label',
  'hj-select-label',
);
export const Value: HanjiPart<typeof Base.Value> = part(
  Base.Value,
  'Select.Value',
  'hj-select-value',
);
export const Backdrop: HanjiPart<typeof Base.Backdrop> = part(
  Base.Backdrop,
  'Select.Backdrop',
  'hj-select-backdrop',
);
export const List: HanjiPart<typeof Base.List> = part(Base.List, 'Select.List', 'hj-select-list');
export const Item: HanjiPart<typeof Base.Item> = part(Base.Item, 'Select.Item', 'hj-select-item');
export const ItemText: HanjiPart<typeof Base.ItemText> = part(
  Base.ItemText,
  'Select.ItemText',
  'hj-select-item-text',
);
export const Group: HanjiPart<typeof Base.Group> = part(
  Base.Group,
  'Select.Group',
  'hj-select-group',
);
export const GroupLabel: HanjiPart<typeof Base.GroupLabel> = part(
  Base.GroupLabel,
  'Select.GroupLabel',
  'hj-select-group-label',
);
export const Separator: HanjiPart<typeof Base.Separator> = part(
  Base.Separator,
  'Select.Separator',
  'hj-select-separator',
);
export const Arrow: HanjiPart<typeof Base.Arrow> = part(
  Base.Arrow,
  'Select.Arrow',
  'hj-select-arrow',
);

/** Portals to `<body>` but keeps the nearest `<Theme>`. */
export function Portal({ children, ...props }: Base.Portal.Props): React.ReactElement {
  return (
    <Base.Portal {...props}>
      <ThemeScope>{children}</ThemeScope>
    </Base.Portal>
  );
}

export interface TriggerOwnProps {
  /** Heights 40 / 48 / 56, matching Field.Control. */
  size?: 'sm' | 'md' | 'lg';
  /** Shown while nothing is selected. Used only when the Trigger has no children. */
  placeholder?: React.ReactNode;
}
export interface TriggerProps extends TriggerOwnProps, Base.Trigger.Props {}

/**
 * The closed select, drawn like a text field. With no children it renders the value (or the
 * placeholder) and a chevron, so `<Select.Trigger placeholder="Choose…" />` is complete.
 */
export function Trigger(props: TriggerProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    size = 'md',
    placeholder,
    className,
    children,
    ...rest
  } = withDefaults(config, 'Select.Trigger', props);
  return (
    <Base.Trigger
      {...rest}
      data-size={size}
      className={cls(config, 'Select.Trigger', 'hj-select-trigger', className)}
    >
      {children ?? (
        <>
          <Value placeholder={placeholder} />
          <Icon />
        </>
      )}
    </Base.Trigger>
  );
}

/** The chevron. Defaults to the adapter's `chevronDown`. */
export function Icon({ children, className, ...props }: Base.Icon.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.Icon {...props} className={cls(config, 'Select.Icon', 'hj-select-icon', className)}>
      {children ?? config.icons.chevronDown}
    </Base.Icon>
  );
}

/** The check beside the chosen item. Defaults to the adapter's `check`. */
export function ItemIndicator({
  children,
  className,
  ...props
}: Base.ItemIndicator.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.ItemIndicator
      {...props}
      className={cls(config, 'Select.ItemIndicator', 'hj-select-item-indicator', className)}
    >
      {children ?? config.icons.check}
    </Base.ItemIndicator>
  );
}

/** Scroll affordance at the top of a long list. */
export function ScrollUpArrow({
  children,
  className,
  ...props
}: Base.ScrollUpArrow.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.ScrollUpArrow
      {...props}
      className={cls(config, 'Select.ScrollUpArrow', 'hj-select-scroll-arrow', className)}
    >
      {children ?? config.icons.chevronUp}
    </Base.ScrollUpArrow>
  );
}

/** Scroll affordance at the bottom of a long list. */
export function ScrollDownArrow({
  children,
  className,
  ...props
}: Base.ScrollDownArrow.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.ScrollDownArrow
      {...props}
      className={cls(config, 'Select.ScrollDownArrow', 'hj-select-scroll-arrow', className)}
    >
      {children ?? config.icons.chevronDown}
    </Base.ScrollDownArrow>
  );
}

/** Places the popup. Gap 6 (hanji menu gap); aligns the chosen item over the trigger by default. */
export function Positioner({
  sideOffset = 6,
  collisionPadding = 8,
  className,
  ...props
}: Base.Positioner.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.Positioner
      {...props}
      sideOffset={sideOffset}
      collisionPadding={collisionPadding}
      className={cls(config, 'Select.Positioner', 'hj-select-positioner', className)}
    />
  );
}

export const Popup: HanjiPart<typeof Base.Popup> = part(
  Base.Popup,
  'Select.Popup',
  'hj-select-popup',
);

export interface OptionOwnProps {
  /** A second line under the label, e.g. a consequence: “about 1.4 GB an hour”. */
  description?: React.ReactNode;
}
export interface OptionProps extends OptionOwnProps, Base.Item.Props {}

/** An Item with its check and text laid out — the common case in one part. */
export function Option({ children, description, ...props }: OptionProps): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Item {...props}>
      <ItemIndicator />
      <ItemText>{children}</ItemText>
      {description ? (
        <span className={config.unstyled ? undefined : 'hj-select-item-description'}>
          {description}
        </span>
      ) : null}
    </Item>
  );
}

export interface ContentOwnProps {
  /** Passed to the Positioner. */
  side?: Base.Positioner.Props['side'];
  align?: Base.Positioner.Props['align'];
  /** Keep the chosen item over the trigger (macOS style). @default true */
  alignItemWithTrigger?: boolean;
  container?: Base.Portal.Props['container'];
}
export interface ContentProps extends ContentOwnProps, Base.Popup.Props {}

/** Shorthand for Portal + Positioner + Popup + scroll arrows + List. Children are the items. */
export function Content({
  side,
  align,
  alignItemWithTrigger,
  container,
  children,
  ...popup
}: ContentProps): React.ReactElement {
  return (
    <Portal container={container}>
      <Positioner side={side} align={align} alignItemWithTrigger={alignItemWithTrigger}>
        <Popup {...popup}>
          <ScrollUpArrow />
          <List>{children}</List>
          <ScrollDownArrow />
        </Popup>
      </Positioner>
    </Portal>
  );
}
